     2	import type { Item } from "./policy.js";
     3	import { payoutRoundedInMHPCOsFavour } from "./rounding.js";
     4	import { reimbursementRateOf } from "./reimbursement-clause.js";
     5	
     6	export interface Damage {
     7	  readonly itemType: string;
     8	  readonly amount: number;
     9	}
    10	
    11	export interface ClaimResult {
    12	  readonly payout: number;
    13	  readonly remainingCap: number;
    14	}
    15	
    16	/**
    17	 * The policyholder bears a deductible on each damaged item, so an incident
    18	 * that damages several items bears it several times -- once per damage
    19	 * entry, which is why the payout is accumulated per entry rather than off
    20	 * the incident's total.
    21	 */
    22	const DEDUCTIBLE = 100;
    23	
    24	/**
    25	 * A payout is money the MHPCO pays out, so it floors at nothing: the
    26	 * deductible can reduce a payout to zero, but a damage smaller than the
    27	 * deductible never turns into a debt owed to the MHPCO.
    28	 */
    29	const NOTHING_PAID_OUT = 0;
    30	
    31	/** What one damage settles at: the reimbursed share, less the deductible. */
    32	function payoutForDamage(items: readonly Item[], damage: Damage): number {
    33	  const reimbursed =
    34	    damage.amount * reimbursementRateOf(damagedItem(items, damage.itemType));
    35	  return Math.max(reimbursed - DEDUCTIBLE, NOTHING_PAID_OUT);
    36	}
    37	
    38	/**
    39	 * What an incident settles at: each damage entry is settled on its own --
    40	 * under the clauses of the item it hit, and bearing its own deductible --
    41	 * and the entries accumulate. An incident that damages nothing settles at
    42	 * nothing.
    43	 */
    44	function incidentPayout(
    45	  items: readonly Item[],
    46	  damages: readonly Damage[],
    47	): number {
    48	  return damages.reduce(
    49	    (total, damage) => total + payoutForDamage(items, damage),
    50	    NOTHING_PAID_OUT,
    51	  );
    52	}
    53	
    54	/** What a draw against the cap takes, and what it leaves behind. */
    55	interface CapDraw {
    56	  readonly drawn: number;
    57	  readonly remainingCap: number;
    58	}
    59	
    60	/**
    61	 * The policy pays no more than its cap still allows, so a payout the cap
    62	 * cannot cover is reduced to what is left of it -- and once the cap is
    63	 * exhausted it draws nothing at all.
    64	 *
    65	 * What a draw takes and what it leaves are one fact about the cap, stated
    66	 * here together so that neither can be revised without the other.
    67	 *
    68	 * The cap is a separate limit from the clauses and the deductible: those
    69	 * decide what the MHPCO owes for a damage, whereas the cap decides how much
    70	 * a policy can still pay out at all, and the MHPCO revises the two on their
    71	 * own schedules -- which is why drawing against the cap is stated apart from
    72	 * what a damage settles at.
    73	 */
    74	function drawAgainstCap(capBeforeClaim: number, desiredPayout: number): CapDraw {
    75	  const drawn = Math.min(desiredPayout, capBeforeClaim);
    76	  return { drawn, remainingCap: capBeforeClaim - drawn };
    77	}
    78	
    79	/**
    80	 * What the incident settles at as a final payout: whole G, rounded in the
    81	 * MHPCO's favour.
    82	 *
    83	 * The rounding happens here, before the cap is drawn against, rather than on
    84	 * whatever the draw yields. The clauses and the deductible are the
    85	 * calculation, and its result is the final payout the spec has rounded; the
    86	 * cap is a limit applied to that finished amount, not a further step of the
    87	 * calculation. Rounding first is also what keeps the cap's ledger honest:
    88	 * the policy is debited exactly the whole G it pays out, so the payout and
    89	 * the remaining cap always add back up to the cap before the claim.
    90	 *
    91	 * Under the present rules the alternative ordering is indistinguishable --
    92	 * a cap is always whole G, so a draw that binds yields that same whole
    93	 * number either way -- which is precisely why the choice is stated here by
    94	 * name instead of being left implicit in the order of two calls.
    95	 */
    96	function finalPayoutFor(
    97	  items: readonly Item[],
    98	  damages: readonly Damage[],
    99	): number {
   100	  return payoutRoundedInMHPCOsFavour(incidentPayout(items, damages));
   101	}
   102	
   103	/**
   104	 * Settling an incident against the policy that covers it: what the incident
   105	 * settles at, and what it leaves of the policy's cap.
   106	 */
   107	export function claim(
   108	  items: readonly Item[],
   109	  damages: readonly Damage[],
   110	  capBeforeClaim: number,
   111	): ClaimResult {
   112	  const { drawn, remainingCap } = drawAgainstCap(
   113	    capBeforeClaim,
   114	    finalPayoutFor(items, damages),
   115	  );
   116	  return { payout: drawn, remainingCap };
   117	}
