     3	/**
     4	 * Matching a damage entry to the insured item it hit.
     5	 *
     6	 * This is its own decision, separate from what a damage settles at: it
     7	 * answers "which covered item was this?", not "what does the MHPCO pay?".
     8	 * The two change for different reasons and on different schedules -- the
     9	 * deductible is a figure the MHPCO revises, whereas matching is a question
    10	 * about the policy's contents, and the spec has it moving once more on its
    11	 * own: an incident may name the same type twice and must then consume two
    12	 * distinct insured items.
    13	 */
    14	
    15	/** The insured item a damage of this type hit. */
    16	export function damagedItem(items: readonly Item[], itemType: string): Item {
    17	  const insured = items.find((item) => item.type === itemType);
    18	  if (insured === undefined) {
    19	    throw new Error(
    20	      `This policy does not cover an item of type "${itemType}"`,
    21	    );
    22	  }
    23	  return insured;
    24	}
