     1	/**
     2	 * What insured items contribute to a premium, before policy-wide modifiers.
     3	 *
     4	 * The two contributions are kept apart all the way up because policy-wide
     5	 * modifiers scale only the policy base premium: a risk surcharge has already
     6	 * been assessed against its own item and must not be scaled again.
     7	 */
     8	export interface ItemPricing {
     9	  /** Sum of item base premiums -- the policy base premium. */
    10	  readonly basePremium: number;
    11	  /** Item-specific risk surcharges, each on its own item's base premium. */
    12	  readonly riskSurcharges: number;
    13	}
    14	
    15	/** An item that contributes nothing -- the identity for combining pricings. */
    16	export const NO_PRICING: ItemPricing = { basePremium: 0, riskSurcharges: 0 };
    17	
    18	/**
    19	 * Pricings combine by adding each contribution separately: base premiums
    20	 * accumulate into the policy base premium, and risk surcharges accumulate
    21	 * alongside it, because policy-wide modifiers scale only the former.
    22	 */
    23	export function combinedPricing(
    24	  left: ItemPricing,
    25	  right: ItemPricing,
    26	): ItemPricing {
    27	  return {
    28	    basePremium: left.basePremium + right.basePremium,
    29	    riskSurcharges: left.riskSurcharges + right.riskSurcharges,
    30	  };
    31	}
    32	
    33	/** What a whole group of priced items contributes, combined. */
    34	export function combinedPricings(
    35	  pricings: readonly ItemPricing[],
    36	): ItemPricing {
    37	  return pricings.reduce(combinedPricing, NO_PRICING);
    38	}
===== price-list.ts =====
     1	import type { Item } from "./policy.js";
     2	
     3	/**
     4	 * The MHPCO price list states one row per main item type: what the item is
     5	 * insured for, and what insuring it costs. The spec states the two figures
     6	 * together ("Sword: 1000 G insurance value, 100 G base premium"), and the
     7	 * MHPCO revises them together, so they are kept in one row rather than in
     8	 * parallel tables that would have to be kept in step by hand.
     9	 *
    10	 * The list covers main items only. Components (runes, moonstones) are
    11	 * priced elsewhere, by the rules that let them form blocks, so a component
    12	 * type has no row here and is never looked up here: `item-price-rules`
    13	 * decides which rules govern an item and routes components away before the
    14	 * list is consulted. A type that does reach the list without a row is one
    15	 * the MHPCO does not insure at all, and is refused.
    16	 */
    17	interface PriceListRow {
    18	  /** Unstated while no active example has yet fixed this row's figure. */
    19	  readonly insuranceValue?: number;
    20	  readonly basePremium?: number;
    21	}
    22	
    23	const MAIN_ITEM_PRICE_LIST: Readonly<Record<string, PriceListRow>> = {
    24	  sword: { insuranceValue: 1000, basePremium: 100 },
    25	  amulet: { insuranceValue: 600, basePremium: 60 },
    26	  staff: { basePremium: 80 },
    27	  potion: { basePremium: 40 },
    28	};
    29	
    30	/**
    31	 * A figure a row is silent on costs and covers nothing.
    32	 *
    33	 * This is the last remaining fallback in the price list, and it is narrower
    34	 * than it looks: it applies only where a row exists but omits a figure (staff
    35	 * and potion state a base premium and no insurance value), never to a type
    36	 * the list does not carry at all -- such a type is refused outright. It
    37	 * stands only until an example fixes those two insurance values, at which
    38	 * point the rows state both figures and this fallback goes with them.
    39	 */
    40	const UNSTATED = 0;
    41	
    42	/**
    43	 * The MHPCO insures the item types on its price list and no others, so an
    44	 * item it does not recognise is refused rather than quoted at nothing.
    45	 */
    46	function priceListRowOf(item: Item): PriceListRow {
    47	  const row = MAIN_ITEM_PRICE_LIST[item.type];
    48	  if (row === undefined) {
    49	    throw new Error(`The MHPCO does not insure items of type "${item.type}"`);
    50	  }
    51	  return row;
    52	}
    53	
    54	/** What the MHPCO charges to insure one main item of this type, before modifiers. */
    55	export function basePremiumOf(item: Item): number {
    56	  return priceListRowOf(item).basePremium ?? UNSTATED;
    57	}
    58	
    59	/** What the MHPCO's main item price list states this type is insured for. */
    60	export function insuranceValueOf(item: Item): number {
    61	  return priceListRowOf(item).insuranceValue ?? UNSTATED;
    62	}
