import type { Item } from "./policy.js";
import { refuse } from "./refusal.js";

/**
 * Matching a damage entry to the insured item it hit.
 *
 * This is its own decision, separate from what a damage settles at: it
 * answers "which covered item was this?", not "what does the MHPCO pay?".
 * The two change for different reasons and on different schedules -- the
 * deductible is a figure the MHPCO revises, whereas matching is a question
 * about the policy's contents, and the spec has it moving once more on its
 * own: an incident may name the same type twice and must then consume two
 * distinct insured items.
 */

/** The insured item a damage of this type hit. */
export function damagedItem(items: readonly Item[], itemType: string): Item {
  const insured = items.find((item) => item.type === itemType);
  if (insured === undefined) {
    refuse(`This policy does not cover an item of type "${itemType}"`);
  }
  return insured;
}
----
